+/**
+ * m split in proportion to `ratios`, in whole cents, the parts adding up exactly to m. Each part gets the whole
+ * cents of its share of m, and each leftover cent goes to the part with the largest fractional remainder (ties
+ * go to the earlier part). Throws a RangeError for an empty list, a negative ratio, or ratios that sum to 0.
+ */
+export function allocate(m: Money, ratios: readonly number[]): Money[] {
+  if (ratios.length === 0) throw new RangeError("allocate: ratios is empty");
+  if (ratios.some((r) => r < 0)) throw new RangeError("allocate: ratios must not be negative");
+  const total = ratios.reduce((a, b) => a + b, 0);
+  if (total === 0) throw new RangeError("allocate: ratios sum to 0");
+  const shares = ratios.map((r) => (m.cents * r) / total);
+  const bases = shares.map((s) => Math.floor(s));
+  const allocated = bases.reduce((a, b) => a + b, 0);
+  const remainder = m.cents - allocated;
+  const order = shares
+    .map((s, i) => ({ i, remainder: s - bases[i] }))
+    .sort((a, b) => b.remainder - a.remainder || a.i - b.i);
+  for (let k = 0; k < remainder; k++) bases[order[k].i] += 1;
+  return bases.map((cents) => money(cents, m.currency));
+}
+
 /**
  * The amount with two decimals and its symbol: "$12.34", "-$0.50", "€3.00", or "12.34 CHF" for a currency with no
  * symbol. With `symbol` false, the number alone: "12.34", "-0.50".
