+import type { Money } from "./core/money.ts";
+import { allocate } from "./core/money.ts";
+import type { Invoice } from "./invoice.ts";
+
+/**
+ * The invoice total split evenly between `people`, the shares adding up to the cent (allocate hands any leftover
+ * cents to the earliest shares). Throws a RangeError when `people` is not a whole number of at least 1.
+ */
+export function splitBill(invoice: Invoice, people: number): Money[] {
+  if (!Number.isInteger(people) || people < 1) throw new RangeError(`splitBill: ${people} is not a whole number of at least 1`);
+  return allocate(invoice.total, Array(people).fill(1));
+}
