+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { allocate, money, sum } from "../src/core/money.ts";
+import type { Invoice } from "../src/invoice.ts";
+import { splitBill } from "../src/split.ts";
+
+test("allocate divides whole cents, remainder to the largest remainder (ties to the earlier part)", () => {
+  assert.deepEqual(allocate(money(100), [1, 1, 1]), [money(34), money(33), money(33)]);
+  assert.deepEqual(allocate(money(1000), [70, 30]), [money(700), money(300)]);
+  assert.deepEqual(allocate(money(5), [1, 1]), [money(3), money(2)]);
+});
+
+test("allocate's parts always sum to the original amount", () => {
+  const parts = allocate(money(1001, "EUR"), [3, 1, 1, 1]);
+  assert.deepEqual(sum(parts, "EUR"), money(1001, "EUR"));
+  assert.deepEqual(parts, [money(500, "EUR"), money(167, "EUR"), money(167, "EUR"), money(167, "EUR")]);
+});
+
+test("allocate rejects an empty list, a negative ratio, or ratios summing to 0", () => {
+  assert.throws(() => allocate(money(100), []), RangeError);
+  assert.throws(() => allocate(money(100), [1, -1]), RangeError);
+  assert.throws(() => allocate(money(100), [0, 0]), RangeError);
+});
+
+function invoiceOf(total: ReturnType<typeof money>): Invoice {
+  return {
+    number: "INV-1",
+    region: "CA",
+    currency: total.currency,
+    lines: [],
+    subtotal: total,
+    discount: money(0, total.currency),
+    tax: money(0, total.currency),
+    shipping: money(0, total.currency),
+    total,
+  };
+}
+
+test("splitBill divides the total evenly, the shares summing to the cent", () => {
+  const inv = invoiceOf(money(100));
+  assert.deepEqual(splitBill(inv, 3), [money(34), money(33), money(33)]);
+  assert.deepEqual(sum(splitBill(inv, 3)), inv.total);
+});
+
+test("splitBill rejects a non-whole or sub-1 number of people", () => {
+  const inv = invoiceOf(money(1000));
+  assert.throws(() => splitBill(inv, 0), RangeError);
+  assert.throws(() => splitBill(inv, -2), RangeError);
+  assert.throws(() => splitBill(inv, 1.5), RangeError);
+});

