 import type { Money } from "./core/money.ts";
-import { money } from "./core/money.ts";
+import { money, zero } from "./core/money.ts";

 /** Flat shipping by region, in cents. */
 export const SHIPPING_CENTS: Readonly<Record<string, number>> = { CA: 599, NY: 699, TX: 649, OR: 599 };

+/** Orders of at least this many cents ship free. */
+export const FREE_SHIPPING_OVER_CENTS = 7500;
+
 /** Shipping to `region` in `currency`. Throws a RangeError for a region the shop does not ship to. */
 export function shippingFor(region: string, currency: string = "USD"): Money {
   const cents = SHIPPING_CENTS[region];
   if (cents === undefined) throw new RangeError(`shipping: no shipping to region ${region}`);
   return money(cents, currency);
 }
+
+/**
+ * Shipping for an order with `subtotal` shipping to `region`: zero in the subtotal's currency when the subtotal
+ * is at least $75.00, otherwise the flat rate for the region. Throws a RangeError for a region the shop does not
+ * ship to, whatever the subtotal.
+ */
+export function shippingQuote(region: string, subtotal: Money): Money {
+  if (subtotal.cents >= FREE_SHIPPING_OVER_CENTS) {
+    if (SHIPPING_CENTS[region] === undefined) throw new RangeError(`shipping: no shipping to region ${region}`);
+    return zero(subtotal.currency);
+  }
+  return shippingFor(region, subtotal.currency);
+}
