+  assert.deepEqual(shippingQuote("NY", money(9000, "EUR")), money(0, "EUR"));
+  assert.throws(() => shippingQuote("ZZ", money(100)), RangeError);
+  assert.throws(() => shippingQuote("ZZ", money(9000)), RangeError);
