@@ -0,0 +1,26 @@
+import type { Invoice, InvoiceLine } from "./invoice.ts";
+import { negate, isNegative } from "./core/money.ts";
+
+/**
+ * A credit note for `invoice`: the same invoice under `number` with every amount negated (each line's unit and
+ * total, subtotal, discount, tax, shipping and total). Quantities, region and currency stay as they are. The
+ * invoice passed in is not changed.
+ */
+export function creditNote(invoice: Invoice, number: string): Invoice {
+  const lines: InvoiceLine[] = invoice.lines.map((l) => ({ ...l, unit: negate(l.unit), total: negate(l.total) }));
+  return {
+    ...invoice,
+    number,
+    lines,
+    subtotal: negate(invoice.subtotal),
+    discount: negate(invoice.discount),
+    tax: negate(invoice.tax),
+    shipping: negate(invoice.shipping),
+    total: negate(invoice.total),
+  };
+}
+
+/** Is `invoice` a credit note, i.e. does it have a negative total? */
+export function isCreditNote(invoice: Invoice): boolean {
+  return isNegative(invoice.total);
+}
diff --git a/test/refund.test.ts b/test/refund.test.ts
new file mode 100644
