--- /dev/null
+++ b/test/refund.test.ts
@@ -0,0 +1,58 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { money, negate, isNegative } from "../src/core/money.ts";
+import { addToCart, emptyCart } from "../src/cart.ts";
+import { buildInvoice } from "../src/invoice.ts";
+import { creditNote, isCreditNote } from "../src/refund.ts";
+
+const tea = { sku: "TEA", name: "Green tea", price: money(450) };
+const pot = { sku: "POT", name: "Teapot", price: money(2999) };
+const cart = addToCart(addToCart(emptyCart(), tea, 2), pot);
+
+test("negate flips the sign, and negate(0) stays 0", () => {
+  assert.deepEqual(negate(money(500)), money(-500));
+  assert.deepEqual(negate(money(-500)), money(500));
+  const z = negate(money(0));
+  assert.deepEqual(z, money(0));
+  assert.equal(Object.is(z.cents, -0), false);
+});
+
+test("isNegative", () => {
+  assert.equal(isNegative(money(-1)), true);
+  assert.equal(isNegative(money(0)), false);
+  assert.equal(isNegative(money(1)), false);
+});
+
+test("creditNote negates every amount and renumbers the invoice", () => {
+  const inv = buildInvoice("INV-1", cart, "CA", { kind: "percent", percent: 10 });
+  const credit = creditNote(inv, "CN-1");
+
+  assert.equal(credit.number, "CN-1");
+  assert.equal(credit.region, inv.region);
+  assert.equal(credit.currency, inv.currency);
+
+  assert.deepEqual(credit.subtotal, negate(inv.subtotal));
+  assert.deepEqual(credit.discount, negate(inv.discount));
+  assert.deepEqual(credit.tax, negate(inv.tax));
+  assert.deepEqual(credit.shipping, negate(inv.shipping));
+  assert.deepEqual(credit.total, negate(inv.total));
+
+  assert.equal(credit.lines.length, inv.lines.length);
+  credit.lines.forEach((line, i) => {
+    const original = inv.lines[i];
+    assert.equal(line.sku, original.sku);
+    assert.equal(line.quantity, original.quantity);
+    assert.deepEqual(line.unit, negate(original.unit));
+    assert.deepEqual(line.total, negate(original.total));
+  });
+
+  // the original invoice is not changed
+  assert.deepEqual(inv.total, buildInvoice("INV-1", cart, "CA", { kind: "percent", percent: 10 }).total);
+  assert.equal(isNegative(inv.total), false);
+});
+
+test("isCreditNote is true exactly when the total is negative", () => {
+  const inv = buildInvoice("INV-2", cart, "CA");
+  assert.equal(isCreditNote(inv), false);
+  assert.equal(isCreditNote(creditNote(inv, "CN-2")), true);
+});

