@@ -0,0 +1,22 @@
+import type { Invoice, InvoiceLine } from "./invoice.ts";
+import { convert } from "./core/money.ts";
+
+
+/** `invoice` converted into `currency` at `rate`: every amount converted on its own, the currency set on the result. */
+export function convertInvoice(invoice: Invoice, rate: number, currency: string): Invoice {
+  const lines: InvoiceLine[] = invoice.lines.map((l) => ({
+    ...l,
+    unit: convert(l.unit, rate, currency),
+    total: convert(l.total, rate, currency),
+  }));
+  return {
+    ...invoice,
+    currency,
+    lines,
+    subtotal: convert(invoice.subtotal, rate, currency),
+    discount: convert(invoice.discount, rate, currency),
+    tax: convert(invoice.tax, rate, currency),
+    shipping: convert(invoice.shipping, rate, currency),
+    total: convert(invoice.total, rate, currency),
+  };
+}
