+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { money, convert } from "../src/core/money.ts";
+import { addToCart, emptyCart } from "../src/cart.ts";
+import { buildInvoice } from "../src/invoice.ts";
+import { convertInvoice } from "../src/fx.ts";
+
+test("convert scales cents by the rate and rounds halves away from zero", () => {
+  assert.deepEqual(convert(money(1000), 0.9, "EUR"), money(900, "EUR"));
+  assert.deepEqual(convert(money(1), 0.5, "EUR"), money(1, "EUR"));
+  assert.deepEqual(convert(money(-1), 0.5, "EUR"), money(-1, "EUR"));
+});
+
+test("convert rejects a rate that is not a finite number above 0", () => {
+  assert.throws(() => convert(money(1000), 0, "EUR"), RangeError);
+  assert.throws(() => convert(money(1000), -1, "EUR"), RangeError);
+  assert.throws(() => convert(money(1000), NaN, "EUR"), RangeError);
+  assert.throws(() => convert(money(1000), Infinity, "EUR"), RangeError);
+});
+
+const tea = { sku: "TEA", name: "Green tea", price: money(450) };
+const pot = { sku: "POT", name: "Teapot", price: money(2999) };
+const cart = addToCart(addToCart(emptyCart(), tea, 2), pot);
+
+test("convertInvoice converts every amount and sets the currency", () => {
+  const inv = buildInvoice("INV-1", cart, "CA");
+  const eur = convertInvoice(inv, 0.9, "EUR");
+  assert.equal(eur.currency, "EUR");
+  assert.deepEqual(eur.lines.map((l) => [l.sku, l.unit, l.total]), [
+    ["TEA", convert(tea.price, 0.9, "EUR"), convert(money(900), 0.9, "EUR")],
+    ["POT", convert(pot.price, 0.9, "EUR"), convert(money(2999), 0.9, "EUR")],
+  ]);
+  assert.deepEqual(eur.subtotal, convert(inv.subtotal, 0.9, "EUR"));
+  assert.deepEqual(eur.discount, convert(inv.discount, 0.9, "EUR"));
+  assert.deepEqual(eur.tax, convert(inv.tax, 0.9, "EUR"));
+  assert.deepEqual(eur.shipping, convert(inv.shipping, 0.9, "EUR"));
+  assert.deepEqual(eur.total, convert(inv.total, 0.9, "EUR"));
+});

