@@ -0,0 +1,23 @@
+import { format, isZero } from "./core/money.ts";
+import type { Invoice } from "./invoice.ts";
+
+/**
+ * Invoice as CSV: the header "sku,name,quantity,unit,total", one row per invoice line, then "subtotal", "discount"
+ * (left out when the discount is zero), "tax", "shipping" and "total" rows written "label,,,,amount". Every amount
+ * is written without a currency symbol. Rows are joined with "\n" with no trailing newline.
+ */
+export function invoiceCsv(invoice: Invoice): string {
+  const header = "sku,name,quantity,unit,total";
+  const lineRows = invoice.lines.map(
+    (l) => `${l.sku},${l.name},${l.quantity},${format(l.unit, false)},${format(l.total, false)}`,
+  );
+  const summary: Array<[string, typeof invoice.subtotal]> = [
+    ["subtotal", invoice.subtotal],
+    ...(isZero(invoice.discount) ? [] : ([["discount", invoice.discount]] as const)),
+    ["tax", invoice.tax],
+    ["shipping", invoice.shipping],
+    ["total", invoice.total],
+  ];
+  const summaryRows = summary.map(([label, amount]) => `${label},,,,${format(amount, false)}`);
+  return [header, ...lineRows, ...summaryRows].join("\n");
+}
