+import type { Money } from "./core/money.ts";
+import { add, percentOf, roundUp } from "./core/money.ts";
+
+/** The tip percentages suggested at checkout. */
+export const TIP_PERCENTS = [15, 18, 20];
+
+/** The suggested tips on `total`, one entry per percent in TIP_PERCENTS, in that order. */
+export function suggestTips(total: Money): Array<{ percent: number; tip: Money; withTip: Money }> {
+  return TIP_PERCENTS.map((percent) => {
+    const tip = percentOf(total, percent);
+    return { percent, tip, withTip: add(total, tip) };
+  });
+}
+
+/** `total` plus its tip at `percent`, rounded up to a whole unit. */
+export function roundedTotal(total: Money, percent: number): Money {
+  return roundUp(add(total, percentOf(total, percent)), 100);
+}
