+import type { Money } from "./core/money.ts";
+import { percentOf, times, zero } from "./core/money.ts";
+import type { Invoice } from "./invoice.ts";
+
+/** The percentage charged for every started 30-day period an invoice is late. */
+export const LATE_FEE_PERCENT = 2;
+
+/**
+ * The late fee on `invoice` when it is `daysLate` days overdue: LATE_FEE_PERCENT percent of the invoice total for
+ * every started 30-day period. Zero in the invoice's currency when `daysLate` is 0 or less.
+ */
+export function lateFee(invoice: Invoice, daysLate: number): Money {
+  if (daysLate <= 0) return zero(invoice.currency);
+  const periods = Math.ceil(daysLate / 30);
+  return times(percentOf(invoice.total, LATE_FEE_PERCENT), periods);
+}
