+import type { Invoice } from "./invoice.ts";
+import { subtract, wholeUnits } from "./core/money.ts";
+
+/**
+ * Loyalty points earned on an invoice: one point per whole unit of currency spent on goods (the subtotal minus the
+ * discount). Tax and shipping earn nothing, and a negative result earns 0.
+ */
+export function pointsFor(invoice: Invoice): number {
+  const net = subtract(invoice.subtotal, invoice.discount);
+  const points = wholeUnits(net);
+  return points < 0 ? 0 : points;
+}
