+});
+
+test("round half-even", () => {
+  assert.equal(round(2.5, "half-even"), 2);
+  assert.equal(round(3.5, "half-even"), 4);
+  assert.equal(round(-2.5, "half-even"), -2);
+});
+
+test("round down", () => {
+  assert.equal(round(2.7, "down"), 2);
+  assert.equal(round(-2.7, "down"), -2);
+});
+
+test("round up", () => {
+  assert.equal(round(2.1, "up"), 3);
+  assert.equal(round(-2.1, "up"), -3);
