+/** The smallest and the largest of `amounts`. Throws a RangeError for an empty list and a TypeError on mixed currencies. */
+export function range(amounts: readonly Money[]): { low: Money; high: Money } {
+  if (amounts.length === 0) throw new RangeError("range: no amounts");
+  let low = amounts[0];
+  let high = amounts[0];
+  for (const m of amounts.slice(1)) {
+    sameCurrency(low, m);
+    if (m.cents < low.cents) low = m;
+    if (m.cents > high.cents) high = m;
+  }
+  return { low, high };
+}
